#include "stdlib/lapack/base/dsyconvf_rook.h"
#include "stdlib/blas/base/dswap.h"
#include "validation.h"

/**
* Swaps row fragments using the existing configured-width DSWAP dependency.
*
* Validation has already checked every physical index and the dependency's
* post-iteration integer arithmetic. Rebasing avoids narrowing matrix offsets.
*/
static void dsyconvf_rook_swap( double *A, const intmax_t strideA1, const intmax_t strideA2, const intmax_t offsetA, const intmax_t row1, const intmax_t row2, const intmax_t column, const intmax_t count ) {
	intmax_t offset1;
	intmax_t offset2;

	if ( row1 == row2 || count == 0 ) {
		return;
	}
	offset1 = offsetA+row1*strideA1+column*strideA2;
	offset2 = offsetA+row2*strideA1+column*strideA2;
	API_SUFFIX(c_dswap_ndarray)( (CBLAS_INT)count, A+offset1, (CBLAS_INT)strideA2, 0, A+offset2, (CBLAS_INT)strideA2, 0 );
}

/**
* Converts or reverts symmetric rook factor storage using alternative indexing.
*
* @param uplo        stored matrix triangle
* @param way         'C'/'c' to convert or 'R'/'r' to revert
* @param N           matrix order
* @param A           input/output factor storage
* @param strideA1    first matrix dimension stride
* @param strideA2    second matrix dimension stride
* @param offsetA     matrix starting index
* @param E           extracted or supplied off-diagonal entries of D
* @param strideE     E stride
* @param offsetE     E starting index
* @param IPIV        read-only, signed one-based LAPACK rook pivots
* @param strideIPIV  IPIV stride
* @param offsetIPIV  IPIV starting index
* @return            zero or a negative one-based argument position
*/
LAPACK_INT API_SUFFIX(c_dsyconvf_rook_ndarray)( const LAPACK_UPLO uplo, const char way, const LAPACK_INT N, double *A, const LAPACK_INT strideA1, const LAPACK_INT strideA2, const LAPACK_INT offsetA, double *E, const LAPACK_INT strideE, const LAPACK_INT offsetE, const LAPACK_INT *IPIV, const LAPACK_INT strideIPIV, const LAPACK_INT offsetIPIV ) {
	const intmax_t n = (intmax_t)N;
	const int convert = way == 'C' || way == 'c';
	LAPACK_INT info;
	intmax_t target1;
	intmax_t target2;
	intmax_t count;
	intmax_t index;
	intmax_t i;

	info = dsyconvf_rook_validate( uplo, way, N, A, strideA1, strideA2, offsetA, E, strideE, offsetE, IPIV, strideIPIV, offsetIPIV );
	if ( info != 0 ) {
		return dsyconvf_rook_error( "c_dsyconvf_rook_ndarray", info );
	}
	if ( N == 0 ) {
		return 0;
	}
	if ( uplo == LAPACK_UPPER_TRIANGLE ) {
		if ( convert ) {
			// Extract all 2-by-2 block values before applying any permutation.
			E[ offsetE ] = 0.0;
			i = n-1;
			while ( i > 0 ) {
				if ( IPIV[ (intmax_t)offsetIPIV+i*strideIPIV ] < 0 ) {
					index = (intmax_t)offsetA+(i-1)*strideA1+i*strideA2;
					E[ (intmax_t)offsetE+i*strideE ] = A[ index ];
					E[ (intmax_t)offsetE+(i-1)*strideE ] = 0.0;
					A[ index ] = 0.0;
					i -= 1;
				} else {
					E[ (intmax_t)offsetE+i*strideE ] = 0.0;
				}
				i -= 1;
			}
			// Upper factorization order: second pair row, then first pair row.
			i = n-1;
			while ( i >= 0 ) {
				target1 = IPIV[ (intmax_t)offsetIPIV+i*strideIPIV ];
				count = n-i-1;
				if ( target1 > 0 ) {
					dsyconvf_rook_swap( A, strideA1, strideA2, offsetA, i, target1-1, i+1, count );
				} else {
					target1 = -target1-1;
					target2 = -((intmax_t)IPIV[ (intmax_t)offsetIPIV+(i-1)*strideIPIV ])-1;
					dsyconvf_rook_swap( A, strideA1, strideA2, offsetA, i, target1, i+1, count );
					dsyconvf_rook_swap( A, strideA1, strideA2, offsetA, i-1, target2, i+1, count );
					i -= 1;
				}
				i -= 1;
			}
		} else {
			// Reverse the permutation order before restoring block values.
			i = 0;
			while ( i < n ) {
				target1 = IPIV[ (intmax_t)offsetIPIV+i*strideIPIV ];
				if ( target1 > 0 ) {
					dsyconvf_rook_swap( A, strideA1, strideA2, offsetA, target1-1, i, i+1, n-i-1 );
				} else {
					i += 1;
					target1 = -((intmax_t)IPIV[ (intmax_t)offsetIPIV+i*strideIPIV ])-1;
					target2 = -((intmax_t)IPIV[ (intmax_t)offsetIPIV+(i-1)*strideIPIV ])-1;
					count = n-i-1;
					dsyconvf_rook_swap( A, strideA1, strideA2, offsetA, target2, i-1, i+1, count );
					dsyconvf_rook_swap( A, strideA1, strideA2, offsetA, target1, i, i+1, count );
				}
				i += 1;
			}
			i = n-1;
			while ( i > 0 ) {
				if ( IPIV[ (intmax_t)offsetIPIV+i*strideIPIV ] < 0 ) {
					A[ (intmax_t)offsetA+(i-1)*strideA1+i*strideA2 ] = E[ (intmax_t)offsetE+i*strideE ];
					i -= 1;
				}
				i -= 1;
			}
		}
	} else if ( convert ) {
		E[ (intmax_t)offsetE+(n-1)*strideE ] = 0.0;
		i = 0;
		while ( i < n ) {
			if ( i < n-1 && IPIV[ (intmax_t)offsetIPIV+i*strideIPIV ] < 0 ) {
				index = (intmax_t)offsetA+(i+1)*strideA1+i*strideA2;
				E[ (intmax_t)offsetE+i*strideE ] = A[ index ];
				E[ (intmax_t)offsetE+(i+1)*strideE ] = 0.0;
				A[ index ] = 0.0;
				i += 1;
			} else {
				E[ (intmax_t)offsetE+i*strideE ] = 0.0;
			}
			i += 1;
		}
		// Lower factorization order: first pair row, then second pair row.
		i = 0;
		while ( i < n ) {
			target1 = IPIV[ (intmax_t)offsetIPIV+i*strideIPIV ];
			if ( target1 > 0 ) {
				dsyconvf_rook_swap( A, strideA1, strideA2, offsetA, i, target1-1, 0, i );
			} else {
				target1 = -target1-1;
				target2 = -((intmax_t)IPIV[ (intmax_t)offsetIPIV+(i+1)*strideIPIV ])-1;
				dsyconvf_rook_swap( A, strideA1, strideA2, offsetA, i, target1, 0, i );
				dsyconvf_rook_swap( A, strideA1, strideA2, offsetA, i+1, target2, 0, i );
				i += 1;
			}
			i += 1;
		}
	} else {
		i = n-1;
		while ( i >= 0 ) {
			target1 = IPIV[ (intmax_t)offsetIPIV+i*strideIPIV ];
			if ( target1 > 0 ) {
				dsyconvf_rook_swap( A, strideA1, strideA2, offsetA, target1-1, i, 0, i );
			} else {
				i -= 1;
				target1 = -((intmax_t)IPIV[ (intmax_t)offsetIPIV+i*strideIPIV ])-1;
				target2 = -((intmax_t)IPIV[ (intmax_t)offsetIPIV+(i+1)*strideIPIV ])-1;
				dsyconvf_rook_swap( A, strideA1, strideA2, offsetA, target2, i+1, 0, i );
				dsyconvf_rook_swap( A, strideA1, strideA2, offsetA, target1, i, 0, i );
			}
			i -= 1;
		}
		i = 0;
		while ( i < n-1 ) {
			if ( IPIV[ (intmax_t)offsetIPIV+i*strideIPIV ] < 0 ) {
				A[ (intmax_t)offsetA+(i+1)*strideA1+i*strideA2 ] = E[ (intmax_t)offsetE+i*strideE ];
				i += 1;
			}
			i += 1;
		}
	}
	return 0;
}
